suppressPackageStartupMessages({library(Seurat);library(SeuratObject);library(ggplot2);library(patchwork);library(dplyr)})
stopifnot(requireNamespace("qs",quietly=TRUE),requireNamespace("harmony",quietly=TRUE),requireNamespace("pheatmap",quietly=TRUE),requireNamespace("ggalluvial",quietly=TRUE),requireNamespace("digest",quietly=TRUE),requireNamespace("scattermore",quietly=TRUE))
set.seed(20260915L);options(future.globals.maxSize=300*1024^3);if(requireNamespace("future",quietly=TRUE))future::plan("sequential")
r2<-normalizePath(getwd(),mustWork=TRUE);r1<-normalizePath(file.path(r2,"..","round1"),mustWork=TRUE)
cluster_levels<-function(x)as.character(sort(as.integer(unique(as.character(x)))))
save_pair<-function(p,stem,w=11,h=8.5){ggsave(paste0(stem,".pdf"),p,width=w,height=h,device=grDevices::pdf,limitsize=FALSE);ggsave(paste0(stem,".png"),p,width=w,height=h,dpi=400,bg="white",limitsize=FALSE)}
umap_plot<-function(o,field,reduction="umap_round2",label=FALSE,legend=TRUE){e<-Embeddings(o[[reduction]]);d<-data.frame(x=e[,1],y=e[,2],group=as.character(o[[]][rownames(e),field]));if(grepl("cluster",field))d$group<-factor(d$group,levels=cluster_levels(d$group));n<-nrow(d);ps<-if(n>1e5).24 else if(n>4e4).32 else if(n>2e4).42 else .52;p<-ggplot(d,aes(x,y,colour=group))+geom_point(size=ps,alpha=.92,stroke=0)+labs(x="UMAP_1",y="UMAP_2",colour=field)+theme_classic(base_size=11)+theme(panel.grid=element_blank(),plot.background=element_rect(fill="white",colour=NA),panel.background=element_rect(fill="white",colour=NA),legend.key.height=grid::unit(.34,"cm"),legend.text=element_text(size=8),legend.title=element_text(size=9))+guides(colour=guide_legend(override.aes=list(size=2.2,alpha=1),ncol=if(length(unique(d$group))>30)2 else 1));if(label){ce<-aggregate(cbind(x,y)~group,d,median);p<-p+geom_label(data=ce,aes(label=group),colour="black",fill=scales::alpha("white",.84),size=2.8,linewidth=.12,label.padding=grid::unit(.09,"lines"),show.legend=FALSE)};if(!legend)p<-p+theme(legend.position="none");p}
dotplot_grouped<-function(o,panel,cluster_field,stem){panel<-panel[order(panel$marker_order),,drop=FALSE];genes<-panel$gene;raw0<-DotPlot(o,features=unique(genes),group.by=cluster_field,assay="RNA",scale=TRUE)$data;raw<-do.call(rbind,lapply(seq_along(genes),function(i){z<-raw0[as.character(raw0$features.plot)==genes[i],,drop=FALSE];z$x<-i;z}));raw$y<-factor(as.character(raw$id),levels=rev(cluster_levels(raw$id)));groups<-unique(panel$marker_group);panel$gf<-factor(panel$marker_group,levels=groups);pal<-setNames(scales::hue_pal(l=88,c=45)(length(groups)),groups);strip<-ggplot(panel,aes(marker_order,1,fill=gf))+geom_tile(width=.98,height=.72,colour="white",linewidth=.35)+geom_text(data=aggregate(marker_order~marker_group,panel,mean),aes(marker_order,1,label=marker_group),inherit.aes=FALSE,angle=45,hjust=0,vjust=.5,size=2.5)+scale_fill_manual(values=pal,guide="none")+scale_x_continuous(limits=c(.5,nrow(panel)+.5),expand=c(0,0))+coord_cartesian(clip="off")+theme_void()+theme(plot.margin=margin(24,8,0,48));bounds<-head(cumsum(table(factor(panel$marker_group,levels=groups))),-1)+.5;main<-ggplot(raw,aes(x,y))+geom_point(aes(size=pct.exp,colour=avg.exp.scaled))+scale_x_continuous(breaks=seq_along(genes),labels=genes,limits=c(.5,length(genes)+.5),expand=c(0,0))+scale_size_continuous(name="Percent Expressed",range=c(0,6),limits=c(0,100),breaks=c(0,25,50,75,100))+scale_colour_gradient(name="Average Expression",low="#D9EAF4",high="#B2182B")+labs(x=NULL,y="Cluster")+theme_classic(base_size=10)+theme(panel.grid=element_blank(),axis.text.x=element_text(angle=45,hjust=1,size=8.5),axis.text.y=element_text(size=9),legend.position="right",legend.box="vertical",legend.title=element_text(size=9),legend.text=element_text(size=8));if(length(bounds))main<-main+geom_vline(xintercept=bounds,colour="grey55",linewidth=.35);p<-strip/main+plot_layout(heights=c(1.35,max(5,length(levels(raw$y))*.3)),guides="collect");save_pair(p,stem,max(13,nrow(panel)*.26),max(8,length(levels(raw$y))*.34+1.5))}
composition<-function(meta,cl,grp){z<-as.data.frame(table(cluster=as.character(meta[[cl]]),group=as.character(meta[[grp]])),stringsAsFactors=FALSE);names(z)[3]<-"n_cells";z<-z[z$n_cells>0,,drop=FALSE];z$proportion_within_cluster<-ave(z$n_cells,z$cluster,FUN=function(x)x/sum(x));z}
write_composition<-function(o,out,cl,suffix="_round2"){m<-o[[]];cs<-composition(m,cl,"orig.ident");cd<-composition(m,cl,"dataset");write.csv(cs[,1:3],file.path(out,paste0("cluster_by_specimen_counts",suffix,".csv")),row.names=FALSE);write.csv(cs[,c(1,2,4)],file.path(out,paste0("cluster_by_specimen_proportions",suffix,".csv")),row.names=FALSE);write.csv(cd[,1:3],file.path(out,paste0("cluster_by_dataset_counts",suffix,".csv")),row.names=FALSE);write.csv(cd[,c(1,2,4)],file.path(out,paste0("cluster_by_dataset_proportions",suffix,".csv")),row.names=FALSE);summ<-bind_rows(lapply(cluster_levels(m[[cl]]),function(k){s<-cs[cs$cluster==k,];d<-cd[cd$cluster==k,];data.frame(cluster=k,n_cells=sum(s$n_cells),n_specimens=nrow(s),n_datasets=nrow(d),max_specimen=max(s$proportion_within_cluster),top_specimen=s$group[which.max(s$proportion_within_cluster)],max_dataset=max(d$proportion_within_cluster),top_dataset=d$group[which.max(d$proportion_within_cluster)])}));summ$warning_single_specimen_gt50<-summ$max_specimen>.5;summ$warning_single_dataset_gt70<-summ$max_dataset>.7;summ$warning_very_small<-summ$n_cells<50;summ$warning_very_few_specimens<-summ$n_specimens<=2;summ$warning_dataset_specific_island<-summ$max_dataset>.9;write.csv(summ,file.path(out,paste0("composition_audit_summary",suffix,".csv")),row.names=FALSE);summ}
write_mapping<-function(o,out,newcl,suffix=""){a<-factor(as.character(o$cluster_v2_round1),levels=cluster_levels(o$cluster_v2_round1));b<-factor(as.character(o[[newcl,drop=TRUE]]),levels=cluster_levels(o[[newcl,drop=TRUE]]));cnt<-table(a,b);rowp<-prop.table(cnt,1);colp<-prop.table(cnt,2);write.csv(cbind(cluster_v2_round1=rownames(cnt),as.data.frame.matrix(cnt)),file.path(out,paste0("round1_to_round2_cluster_counts",suffix,".csv")),row.names=FALSE);write.csv(cbind(cluster_v2_round1=rownames(rowp),as.data.frame.matrix(rowp)),file.path(out,paste0("round1_to_round2_cluster_row_proportions",suffix,".csv")),row.names=FALSE);write.csv(cbind(cluster_v2_round1=rownames(colp),as.data.frame.matrix(colp)),file.path(out,paste0("round1_to_round2_cluster_column_proportions",suffix,".csv")),row.names=FALSE);pdf(file.path(out,paste0("round1_to_round2_cluster_heatmap",suffix,".pdf")),width=10,height=8);pheatmap::pheatmap(rowp,cluster_rows=FALSE,cluster_cols=FALSE);dev.off();png(file.path(out,paste0("round1_to_round2_cluster_heatmap",suffix,".png")),width=3600,height=3000,res=350);pheatmap::pheatmap(rowp,cluster_rows=FALSE,cluster_cols=FALSE);dev.off();flow<-as.data.frame(cnt);names(flow)<-c("Round1","Round2","n");flow<-flow[flow$n>0,];pa<-ggplot(flow,aes(axis1=Round1,axis2=Round2,y=n))+ggalluvial::geom_alluvium(aes(fill=Round1),alpha=.8)+ggalluvial::geom_stratum(width=.25,fill="white",colour="grey35")+ggalluvial::stat_stratum(geom="text",aes(label=after_stat(stratum)),size=3)+scale_x_discrete(limits=c("Round1","Round2"),expand=c(.08,.08))+theme_classic()+theme(legend.position="none",panel.grid=element_blank())+labs(x=NULL,y="Cells");try(save_pair(pa,file.path(out,paste0("round1_to_round2_alluvial",suffix)),10,8),silent=TRUE);list(counts=cnt,rowp=rowp,colp=colp)}
write_markers<-function(o,out,cl,suffix="_round2"){Idents(o)<-cl;mk<-FindAllMarkers(o,assay="RNA",only.pos=TRUE,min.pct=.1,logfc.threshold=.25,return.thresh=.05,verbose=TRUE);if(!"gene"%in%names(mk))mk$gene<-rownames(mk);for(x in setdiff(c("cluster","gene","avg_log2FC","pct.1","pct.2","p_val","p_val_adj"),names(mk)))mk[[x]]<-NA;write.csv(mk,file.path(out,paste0("markers_all",suffix,".csv")),row.names=FALSE);rk<-mk%>%group_by(cluster)%>%arrange(p_val_adj,desc(avg_log2FC),.by_group=TRUE);write.csv(rk%>%slice_head(n=10)%>%ungroup(),file.path(out,paste0("markers_top10_per_cluster",suffix,".csv")),row.names=FALSE);write.csv(rk%>%slice_head(n=20)%>%ungroup(),file.path(out,paste0("markers_top20_per_cluster",suffix,".csv")),row.names=FALSE);nrow(mk)}
decision_template<-function(o,out,cl,map){sizes<-as.data.frame(table(cluster_round2=o[[cl,drop=TRUE]]),stringsAsFactors=FALSE);names(sizes)[2]<-"n_cells";src<-sapply(as.character(sizes$cluster_round2),function(k){z<-sort(map$colp[,k],decreasing=TRUE);paste(names(z)[z>=.1][1:min(3,sum(z>=.1))],collapse=";")});x<-data.frame(cluster_round2=as.character(sizes$cluster_round2),n_cells=sizes$n_cells,major_round1_sources=src,proposed_subtype="",confidence="",merge_to="",notes="",check.names=FALSE);write.csv(x,file.path(out,"annotation_decision_template_round2.csv"),row.names=FALSE,na="")}
